INSERT INTO "public"."projects" ("id", "name", "created_at") VALUES (10, 'Project Horizon', '2026-08-16 14:46:27.150802'), (12, 'Test', '2026-08-16 15:19:13.335691');
INSERT INTO "public"."tasks" ("id", "project_id", "title", "description", "status", "priority", "assigned_to", "created_by", "due_date", "created_at") VALUES (21, 10, 'Address Security bugs on the ticketing platform', 'Audit has raised concerns about security vulnerabilities in the ticketing platform. There is a lack of access controls due to constant change in staff over the last few months. The Audit team identified that several terminated employees still seemed to have access to the platform. These access issues need to be addressed before the audit filing deadline. ', 'To Do', 'Medium', 8, 5, '2026-10-15 00:00:00', '2026-08-16 14:55:47.59196'), (23, 10, 'Resolve tickets related to the Horizon dashboard', 'Since the dashboard is still in its early stages, there are a few technical bugs and feedback from the users. Address them as and when they occur', 'To Do', 'High', 6, 5, '2026-08-31 00:00:00', '2026-08-16 15:01:43.608327'), (24, 10, 'Test Chat bots', 'To execute the holistic goal of Project Horizon, the execution of AI chatbots is vital. It is a high priority item for the team to test the chatbot and prepare it for implementation as soon as possible.', 'In Progress', 'High', 7, 5, '2026-09-11 00:00:00', '2026-08-16 15:10:04.98248'), (25, 10, 'Onboarding Task', 'Since Project Horizon is a large-scale project, several new hires have been assigned to assist the team in its implementation. Please set up some time with the hires to introduce the project, deadlines, and other relevant information regarding the project', 'In Progress', 'Medium', 6, 9, '2026-08-31 00:00:00', '2026-08-16 15:11:26.801972'), (27, 12, 'Task 1', '', 'In Progress', 'Medium', 6, 9, '2026-09-01 00:00:00', '2026-08-16 15:20:10.876488'), (28, 12, 'Task 2', '', 'To Do', 'High', 10, 9, '2026-08-28 00:00:00', '2026-08-16 15:20:36.817477'), (29, 12, 'Task 3', '', 'To Do', 'Low', 6, 9, '2026-09-30 00:00:00', '2026-08-16 15:21:05.3533');
